/**
 * js/network.js
 * Arc-length parameterised road network for the deterministic traffic simulation.
 *
 * Loads NETWORK_DATA (generated by Scripts/generate_network.py from
 * Data/GeoJSON/bengaluru_network.json) and turns each directed edge into a polyline
 * with a cumulative arc-length table, so vehicles can be positioned by distance
 * travelled `s` rather than by interpolating between junction nodes.
 *
 * Browser-global (window.SimulationNetwork) and CommonJS (Node.js) compatible.
 */

(function (root, factory) {
  if (typeof define === 'function' && define.amd) {
    define([], factory);
  } else if (typeof module === 'object' && module.exports) {
    module.exports = factory();
  } else {
    root.SimulationNetwork = factory();
  }
}(typeof self !== 'undefined' ? self : this, function () {
  'use strict';

  const EARTH_RADIUS_M = 6378137.0;
  const DEG2RAD = Math.PI / 180.0;

  // Distance in metres between two [lon, lat] pairs on a sphere.
  function haversineLonLat(a, b) {
    const lat1 = a[1] * DEG2RAD;
    const lat2 = b[1] * DEG2RAD;
    const dLat = lat2 - lat1;
    const dLon = (b[0] - a[0]) * DEG2RAD;
    const h = Math.sin(dLat / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLon / 2) ** 2;
    return 2 * EARTH_RADIUS_M * Math.asin(Math.sqrt(h));
  }

  /**
   * A directed road edge with arc-length parameterisation.
   * Coordinates are [lon, lat, alt] as stored in the network data.
   */
  class SimulationEdge {
    constructor(raw, fromNode, toNode) {
      this.id = raw.id;
      this.name = raw.name;
      this.fromNodeId = raw.from_node;
      this.toNodeId = raw.to_node;
      this.highway = raw.highway;
      this.lanes = raw.lanes || 1;
      this.maxspeedKmh = raw.maxspeed;
      this.speedLimitMps = raw.maxspeed / 3.6;
      this.oneway = !!raw.oneway;
      this.surface = raw.surface;
      this.evPriorityCorridor = !!raw.ev_priority_corridor;
      this.isDividedCarriageway = !!raw.is_divided_carriageway;
      this.carriagewayTag = raw.carriageway_tag || '';
      this.lengthProvenance = raw.length_provenance || 'UNKNOWN';
      this.elevationM = raw.elevation_m || 0.0;

      this.fromNode = fromNode || null;
      this.toNode = toNode || null;

      this.polyline = SimulationEdge.normalisePolyline(raw, this.fromNode, this.toNode);
      this.cumulative = SimulationEdge.buildCumulative(this.polyline);
      this.length = this.cumulative[this.cumulative.length - 1];

      // Stop line sits upstream of the downstream junction's conflict zone.
      // Populated by the network builder once junction geometry is known.
      this.stopLineOffsetM = null;
    }

    static normalisePolyline(raw, fromNode, toNode) {
      const source = Array.isArray(raw.polyline) ? raw.polyline : [];
      const points = source
        .filter((p) => Array.isArray(p) && p.length >= 2 && Number.isFinite(p[0]) && Number.isFinite(p[1]))
        .map((p) => [p[0], p[1], Number.isFinite(p[2]) ? p[2] : (raw.elevation_m || 0.0)]);
      if (points.length >= 2) return points;
      if (fromNode && toNode) {
        return [
          [fromNode.lon, fromNode.lat, fromNode.alt],
          [toNode.lon, toNode.lat, toNode.alt],
        ];
      }
      return [];
    }

    static buildCumulative(polyline) {
      const cumulative = [0.0];
      for (let i = 1; i < polyline.length; i += 1) {
        cumulative.push(cumulative[i - 1] + haversineLonLat(polyline[i - 1], polyline[i]));
      }
      return cumulative;
    }

    /** Index of the polyline segment containing arc-length `s`. */
    segmentIndexAt(s) {
      const clamped = Math.max(0, Math.min(this.length, s));
      let lo = 0;
      let hi = this.cumulative.length - 1;
      while (lo < hi - 1) {
        const mid = (lo + hi) >> 1;
        if (this.cumulative[mid] <= clamped) lo = mid;
        else hi = mid;
      }
      return lo;
    }

    /**
     * Position and tangent heading at arc-length `s`.
     * Heading is a compass bearing in radians (0 = north, +ve = clockwise), taken
     * from the polyline segment so curvature is respected.
     */
    sampleAt(s) {
      if (this.polyline.length < 2) {
        return { lon: 0, lat: 0, alt: this.elevationM, headingRad: 0, s: 0 };
      }
      const clamped = Math.max(0, Math.min(this.length, s));
      let i = this.segmentIndexAt(clamped);
      // Skip zero-length segments (duplicate OSM nodes) so the tangent is meaningful.
      while (i < this.polyline.length - 2 && this.cumulative[i + 1] - this.cumulative[i] < 1e-6) i += 1;
      const a = this.polyline[i];
      const b = this.polyline[Math.min(i + 1, this.polyline.length - 1)];
      const segStart = this.cumulative[i];
      const segLen = this.cumulative[i + 1] - segStart;
      const t = segLen > 1e-9 ? Math.max(0, Math.min(1, (clamped - segStart) / segLen)) : 0;

      const lon = a[0] + (b[0] - a[0]) * t;
      const lat = a[1] + (b[1] - a[1]) * t;
      const alt = a[2] + (b[2] - a[2]) * t;

      // Bearing from segment endpoints, scaled to metres so longitude degrees compress.
      const dNorth = (b[1] - a[1]) * DEG2RAD * EARTH_RADIUS_M;
      const dEast = (b[0] - a[0]) * DEG2RAD * EARTH_RADIUS_M * Math.cos(a[1] * DEG2RAD);
      const headingRad = Math.atan2(dEast, dNorth);

      return { lon, lat, alt, headingRad, s: clamped };
    }

    /** Compass heading in radians at the end of the edge (used for junction handoff). */
    endHeadingRad() {
      return this.sampleAt(this.length).headingRad;
    }
  }

  /**
   * Builds a routable simulation network from NETWORK_DATA.
   */
  class SimulationNetwork {
    constructor(networkData) {
      if (!networkData || !Array.isArray(networkData.nodes) || !Array.isArray(networkData.edges)) {
        throw new Error('SimulationNetwork requires NETWORK_DATA with nodes and edges arrays');
      }
      this.raw = networkData;
      this.nodes = new Map();
      this.edges = new Map();
      this.outgoing = new Map();
      this.incoming = new Map();

      for (const node of networkData.nodes) {
        this.nodes.set(node.id, node);
        this.outgoing.set(node.id, []);
        this.incoming.set(node.id, []);
      }

      for (const raw of networkData.edges) {
        const edge = new SimulationEdge(raw, this.nodes.get(raw.from_node), this.nodes.get(raw.to_node));
        if (edge.polyline.length < 2) continue;
        this.edges.set(edge.id, edge);
        if (this.outgoing.has(edge.fromNodeId)) this.outgoing.get(edge.fromNodeId).push(edge.id);
        if (this.incoming.has(edge.toNodeId)) this.incoming.get(edge.toNodeId).push(edge.id);
      }

      this.hospitals = new Map();
      for (const hospital of (networkData.hospitals || [])) {
        this.hospitals.set(hospital.id, hospital);
      }

      // All nodes that have a signals array with at least one entry
      const signalised = new Set(
        networkData.nodes
          .filter((n) => Array.isArray(n.signals) && n.signals.length > 0)
          .map((n) => n.id)
      );
      this.signalisedNodeIds = signalised;

      this.stopLines = new Map();
      this.sensors = new Map();
      this._computeStopLines(signalised);
      this.addSyntheticSensors(signalised);
    }

    /**
     * Place a stop line on every incoming approach to a signalised junction.
     * The line sits `offset` metres upstream of the edge end so queued vehicles
     * halt before the junction conflict zone rather than inside it.
     */
    _computeStopLines(signalisedNodeIds, offsetM = 12.0) {
      const signalNodes = signalisedNodeIds
        ? new Set(signalisedNodeIds)
        : new Set(this.raw.nodes.filter((n) => Array.isArray(n.signals) && n.signals.length > 0).map((n) => n.id));

      this.signalisedNodeIds = signalNodes;
      for (const edge of this.edges.values()) {
        if (!signalNodes.has(edge.toNodeId)) continue;
        const offset = Math.min(offsetM, Math.max(2.0, edge.length * 0.2));
        edge.stopLineOffsetM = edge.length - offset;
        this.stopLines.set(edge.id, {
          edgeId: edge.id,
          nodeId: edge.toNodeId,
          offsetFromStartM: edge.stopLineOffsetM,
          upstreamOfJunctionM: offset,
        });
      }
    }

    getEdge(id) { return this.edges.get(id) || null; }
    getNode(id) { return this.nodes.get(id) || null; }
    getOutgoing(nodeId) { return this.outgoing.get(nodeId) || []; }
    getIncoming(nodeId) { return this.incoming.get(nodeId) || []; }
    getHospital(id) { return this.hospitals.get(id) || null; }
    getEdgeList() { return Array.from(this.edges.values()); }

    /** Every node with at least one outgoing edge that is not reachable from it. */
    validateConnectivity() {
      const seen = new Set();
      const queue = [];
      const startNode = this.raw.nodes[0] && this.raw.nodes[0].id;
      if (startNode) queue.push(startNode);
      while (queue.length) {
        const node = queue.shift();
        if (seen.has(node)) continue;
        seen.add(node);
        for (const edgeId of this.getOutgoing(node)) {
          const edge = this.edges.get(edgeId);
          if (edge) queue.push(edge.toNodeId);
        }
      }
      const unreachable = [];
      for (const nodeId of this.nodes.keys()) {
        if (this.outgoing.get(nodeId).length === 0 && this.incoming.get(nodeId).length === 0) {
          unreachable.push(nodeId);
        } else if (!seen.has(nodeId)) {
          unreachable.push(nodeId);
        }
      }
      return { reachableCount: seen.size, totalNodes: this.nodes.size, unreachable };
    }

    /**
   * Candidate entry edges for spawning. The curated graph is a closed corridor
   * network, so almost every junction has an incoming edge. Rank edges by travel
   * time descending and hand back the slowest approaches: those are the long
   * arterial segments where a spawn has room to accelerate into traffic.
     */
    getEntryEdges(limit = 12) {
      const ranked = this.getEdgeList()
        .filter((edge) => edge.length >= 150)
        .sort((a, b) => (b.length / b.speedLimitMps) - (a.length / a.speedLimitMps));
      return ranked.slice(0, limit);
    }

    /**
     * Place virtual sensors (inductive loops / CCTV) on key corridors.
     * Provenance: "SYNTHETIC_SENSOR" — no live CCTV feed; coverage is declared
     * for the simulation only. Real Bengaluru ITMS CCTV locations are not
     * publicly exposed, so these are representative placements on major
     * arterials and hospital approaches.
     */
    addSyntheticSensors(signalisedNodeIds) {
      const signalNodes = new Set(signalisedNodeIds);
      const sensorNodes = new Set(this.raw.nodes
        .filter((n) => n.type && n.type.includes('hospital'))
        .map((n) => n.id));
      for (const edge of this.edges.values()) {
        if (signalNodes.has(edge.toNodeId) || sensorNodes.has(edge.toNodeId) || signalNodes.has(edge.fromNodeId)) {
          const sensorId = 'sensor_' + edge.id;
          this.sensors.set(sensorId, {
            id: sensorId,
            edgeId: edge.id,
            positionS: edge.length * 0.85, // 85% along from start, just before junction
            coverage: 'incoming',
            provenance: 'SYNTHETIC_SENSOR',
            measures: ['vehicle_count', 'avg_speed_mps', 'queue_length_m'],
          });
        }
      }
      // Add an explicit hospital-approach sensor for each hospital ingress
      for (const hosp of this.hospitals.values()) {
        const ingressNodeId = hosp.ingress_node;
        for (const incomingId of this.getIncoming(ingressNodeId)) {
          const edge = this.edges.get(incomingId);
          if (edge) {
            const sensorId = 'sensor_hosp_' + hosp.id + '_' + incomingId;
            this.sensors.set(sensorId, {
              id: sensorId,
              edgeId: incomingId,
              positionS: edge.length * 0.9,
              coverage: 'hospital_approach',
              provenance: 'SYNTHETIC_SENSOR',
              measures: ['vehicle_count', 'avg_speed_mps', 'queue_length_m', 'ambulance_presence'],
              hospitalId: hosp.id,
            });
          }
        }
      }
    }

    getSensor(id) { return this.sensors.get(id) || null; }
    getAllSensors() { return Array.from(this.sensors.values()); }
    getSensorsOnEdge(edgeId) { return Array.from(this.sensors.values()).filter((s) => s.edgeId === edgeId); }
    getHospitalApproachSensors(hospitalId) {
      return Array.from(this.sensors.values()).filter((s) => s.hospitalId === hospitalId);
    }
  }

  return {
    SimulationNetwork,
    SimulationEdge,
    haversineLonLat,
    EARTH_RADIUS_M,
  };
}));